var Q15 = [
{n:1, q:'Los delitos contra la seguridad vial están castigados en...', o:{a:'El capítulo VI del Título XVI del Código Penal.',b:'El capítulo V del Título XVI del Código Penal.',c:'El capítulo IV del Título XVII del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Los delitos contra la seguridad vial están en el Capítulo IV del Título XVII del Libro II del CP (arts.379-385 ter), no en el Título XVI.'}},
{n:2, q:'Los delitos contra la seguridad vial están castigados en el Código Penal, concretamente en los artículos...', o:{a:'379 a 385-.',b:'379 a 385 bis.',c:'379 a 385 ter.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Los delitos contra la seguridad vial están regulados en los artículos 379 a 385 ter del CP.'}},
{n:3, q:'En nuestro Código Penal, el delito de conducción bajo la influencia de bebidas alcohólicas se castiga en el artículo...', o:{a:'379.1',b:'379.2',c:'379.3',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.379.2 CP: el delito de conducción bajo la influencia de bebidas alcohólicas está tipificado en el artículo 379.2 del CP.'}},
{n:4, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un turismo bajo la influencia de bebidas alcohólicas.',b:'Conducir un ciclomotor bajo la influencia de bebidas alcohólicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.379.2 CP: conducir cualquier vehículo a motor o ciclomotor (turismo o ciclomotor) bajo la influencia de bebidas alcohólicas constituye delito.'}},
{n:5, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un vehículo de movilidad personal bajo la influencia de bebidas alcohólicas.',b:'Conducir una bicicleta de pedaleo asistido bajo la influencia de bebidas alcohólicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.379.2 CP: el delito se limita a vehículos a motor y ciclomotores. Los vehículos de movilidad personal y bicicletas no son vehículos a motor, por lo que no constituyen este delito.'}},
{n:6, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un vehículo de motor bajo la influencia de bebidas alcohólicas.',b:'Conducir un vehículo de tracción animal bajo la influencia de bebidas alcohólicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.379.2 CP: solo constituye delito conducir un vehículo a motor (a) bajo la influencia de bebidas alcohólicas. Los de tracción animal no están incluidos.'}},
{n:7, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir cualquier vehículo bajo la influencia de drogas tóxicas.',b:'Conducir un ciclomotor con presencia de drogas en el organismo.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.379.2 CP: el delito de conducción bajo influencia de drogas se aplica a vehículos a motor y ciclomotores, no a "cualquier vehículo". Además, la mera presencia de drogas en el organismo no es suficiente; se requiere influencia real en la conducción.'}},
{n:8, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir vehículo a motor bajo la influencia de estupefacientes.',b:'Conducir un ciclomotor bajo la influencia de sustancias psicotrópicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.379.2 CP: constituye delito conducir bajo la influencia de drogas tóxicas, estupefacientes (a) o sustancias psicotrópicas (b).'}},
{n:9, q:'Según nuestro Código Penal, el que condujere un vehículo de motor o ciclomotor bajo la influencia de drogas tóxicas, estupefacientes, sustancias psicotrópicas o de bebidas alcohólicas, será castigado con las penas de...', o:{a:'Prisión de tres a seis meses y con la de multa de seis a dieciocho meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.',b:'Prisión de tres a seis meses o con la de multa de seis a dieciocho meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a dos y hasta cuatro años.',c:'Prisión de tres a seis meses o con la de multa de seis a doce meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cinco años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.379.2 CP: la pena es prisión de 3 a 6 meses O multa de 6 a 18 meses O TBC 31-90 días, y en cualquier caso privación del derecho a conducir de más de 1 año y hasta 4 años.'}},
{n:10, q:'Según nuestro Código Penal, el que condujere un vehículo de motor o ciclomotor bajo la influencia de drogas tóxicas, estupefacientes, sustancias psicotrópicas o de bebidas alcohólicas, será castigado con las penas de...', o:{a:'Prisión de tres meses a un año o con la de multa de seis a dieciocho meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.',b:'Prisión de tres a seis meses o con la de multa de seis a doce meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.',c:'Prisión de tres a seis meses o con la de multa de seis a doce meses y con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Ninguna de las opciones reproduce exactamente el texto del art.379.2 CP (que prevé 3-6 meses de prisión O multa 6-18 meses O TBC 31-90 días, y privación del derecho a conducir >1 y hasta 4 años).'}},
{n:11, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un vehículo a motor con una tasa de alcohol en aire espirado superior a 0,60 mg/l.',b:'Conducir un ciclomotor con una tasa de alcohol en sangre superior a 0,60 g/l.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.379.2 CP: constituye delito conducir con tasa de alcohol en aire espirado superior a 0,60 mg/l (a) o en sangre superior a 1,2 g/l. La opción b dice 0,60 g/l en sangre que también supera el umbral penal de 1,2 g/l.'}},
{n:12, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir cualquier vehículo con una tasa de alcohol en aire espirado superior a 0,60 mg/l.',b:'Conducir un ciclomotor con una tasa de alcohol en sangre superior a 1,2 g/l.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.379.2 CP: constituye delito conducir un vehículo a motor o ciclomotor con tasa de alcohol en sangre superior a 1,2 g/l (b). La opción a es incorrecta porque el delito solo aplica a vehículos a motor y ciclomotores, no a "cualquier vehículo".'}},
{n:13, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un vehículo a motor con presencia de drogas en el organismo.',b:'Conducir un ciclomotor con una tasa de alcohol en aire espirado superior a 0,25 mg/l.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La mera presencia de drogas en el organismo no basta para el delito del art.379.2 (requiere "influencia"); y la tasa de 0,25 mg/l en aire espirado tampoco supera el umbral penal de 0,60 mg/l.'}},
{n:14, q:'Una persona de 15 años de edad, que conduce un ciclomotor con una tasa de alcohol en aire espirado de 0,35 mg/l ...', o:{a:'Comete un delito del artículo 379.2 CP.',b:'Comete una infracción administrativa del artículo 14 del RDL 6/2015.',c:'Comete un delito del artículo 380 CP.',d:'No comete infracción alguna.'}, correct:'b', why:{b:'La tasa de 0,35 mg/l en aire espirado no supera el umbral penal de 0,60 mg/l (art.379.2 CP). Constituye infracción administrativa a la Ley de Tráfico.'}},
{n:15, q:'Una persona de 16 años de edad, que conduce un ciclomotor con una tasa de alcohol en aire espirado de 0,10 mg/l ...', o:{a:'Comete un delito del artículo 379.2 CP.',b:'Comete una infracción administrativa del artículo 14 del RDL 6/2015.',c:'Comete un delito del artículo 380 CP.',d:'No comete infracción alguna.'}, correct:'b', why:{b:'Una tasa de 0,10 mg/l en aire espirado está muy por debajo del umbral penal de 0,60 mg/l. Constituye infracción administrativa.'}},
{n:16, q:'El Tribunal Constitucional, en la STC 262/2006, ha sentenciado...', o:{a:'Que para apreciar el delito de conducción influenciada se requiere necesariamente la realización de las pruebas de determinación del grado de impregnación alcohólica.',b:'Que el Juez o Tribunal puede llegar al convencimiento de que se ha realizado una conducción influenciada a partir de los testimonios del propio acusado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'STC 262/2006: el TC ha declarado que el juez puede llegar al convencimiento de la conducción influenciada a partir de los testimonios del propio acusado, sin que sea imprescindible la prueba alcoholométrica.'}},
{n:17, q:'El Tribunal Constitucional, en la STC 262/2006, ha sentenciado...', o:{a:'Que para apreciar el delito de conducción influenciada ni siquiera se exige necesariamente la realización de las pruebas de determinación del grado de impregnación alcohólica.',b:'Que el Juez o Tribunal puede llegar al convencimiento de que se ha realizado una conducción influenciada a partir de los testimonios de los policías intervinientes o de testigos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'STC 262/2006: no se requieren necesariamente las pruebas alcoholométricas (a), y el juez puede convencerse a partir de testimonios policiales o de testigos (b).'}},
{n:18, q:'El Tribunal Supremo, en la STS 436/2017, ha sentenciado que el delito del artículo 379.2 del Código Penal...', o:{a:'Exige de un movimiento locativo, pero no de una conducción durante un determinado espacio de tiempo.',b:'Se puede cometer al aparcar o desaparcar el vehículo, estando bajo la influencia de bebidas alcohólicas.',c:'Puede tener lugar cuando se conduce el vehículo a motor o ciclomotor durante unos pocos metros, bajo la influencia de bebidas alcohólicas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'STS 436/2017: el delito del art.379.2 exige un movimiento locativo pero no una conducción prolongada (a), puede cometerse al aparcar (b) y basta con conducir unos pocos metros (c).'}},
{n:19, q:'La Fiscalía General del Estado, en la Instrucción 3/2006, ha determinado que...', o:{a:'En supuestos de alcoholemia comprendidos entre 0,8 y 1,2 gramos de alcohol por 1.000 c.c. de sangre, las Sras. y Sres. Fiscales acusarán por delito contra la seguridad vial cuando concurran circunstancias tales como la existencia de síntomas de embriaguez en el conductor.',b:'En supuestos de alcoholemia comprendidos entre 0,40 y 0,60 mg de alcohol por litro de aire espirado, las Sras. y Sres. Fiscales acusarán por delito contra la seguridad vial cuando concurran circunstancias tales como la comisión de infracciones reglamentarias que denoten una conducción peligrosa o descuidada o el haber provocado un accidente de circulación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Instrucción FGE 3/2006: establece criterios para acusar en la zona gris de alcoholemia: con sintomatología (a) o con conducción peligrosa/accidente (b).'}},
{n:20, q:'La Fiscalía General del Estado, en la Instrucción 3/2006, ha determinado que...', o:{a:'Si la tasa de alcohol es inferior a 0,80 gr. de alcohol por 1.000 c.c. de sangre las Sras. y Sres. Fiscales no ejercitarán la acción penal por delito del art. 379.2 CP, derivando los hechos a la vía sancionadora administrativa, salvo en aquellos casos singulares en que por concurrir circunstancias que evidencien una efectiva afectación de la capacidad psicofísica para la conducción del imputado, existan indicios bastantes de la comisión de dicho delito.',b:'Si la tasa de alcohol es inferior a 0,50 mg. de alcohol por litro de aire espirado, las Sras. y Sres. Fiscales no ejercitarán la acción penal por delito del art. 379.2 CP, derivando los hechos a la vía sancionadora administrativa, salvo en aquellos casos singulares en que por concurrir circunstancias que evidencien una efectiva afectación de la capacidad psicofísica para la conducción del imputado, existan indicios bastantes de la comisión de dicho delito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Instrucción FGE 3/2006: establece umbrales por debajo de los cuales el MF no ejercitará acción penal salvo circunstancias especiales: <0,80 g/l en sangre (a) y <0,50 mg/l en aire (b).'}},
{n:21, q:'La conducción de vehículos a motor superando las tasas de alcohol reglamentariamente establecidas:', o:{a:'Siempre constituye delito del artículo 379.2 CP.',b:'Siempre constituye infracción administrativa del artículo 20 del Reglamento General de Circulación.',c:'Puede ser constitutiva de delito o de infracción administrativa.',d:'Puede ser atípica en algunos casos.'}, correct:'c', why:{c:'Superar las tasas de alcohol puede constituir delito del art.379.2 CP (si supera 0,60 mg/l en aire o 1,2 g/l en sangre o hay influencia acreditada) o infracción administrativa (si las tasas son menores).'}},
{n:22, q:'Conducir un vehículo de motor o ciclomotor bajo la influencia de bebidas alcohólicas...', o:{a:'Constituye infracción de carácter grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad vial.',b:'Constituye un delito leve tipificado en el artículo 379.2 del Código Penal.',c:'Constituye una infracción de carácter muy grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad vial.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Conducir bajo la influencia de bebidas alcohólicas es un delito menos grave del art.379.2 CP (no leve, no infracción grave), por lo que ninguna opción es exactamente correcta.'}},
{n:23, q:'El Sr. X, titular de un permiso de conducir con un año de antigüedad, es sometido a la prueba de alcoholemia por aire espirado y arroja un resultado de 0,45 mg/litro. Teniendo en cuenta lo anterior, indique la respuesta correcta:', o:{a:'El Sr. X es autor de un delito contra la seguridad vial, si se aprecia influencia del alcohol en su conducción.',b:'El Sr. X es autor de una infracción administrativa a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad vial, si no se aprecia influencia del alcohol en su conducción.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Con 0,45 mg/l en aire espirado (por debajo del umbral penal de 0,60 mg/l), si hay influencia acreditada → delito (a); si no hay influencia → infracción administrativa (b).'}},
{n:24, q:'Para que la tasa de alcohol obtenida en un conductor sea constitutiva de delito se requiere:', o:{a:'Que el vehículo conducido sea de motor o ciclomotor.',b:'Que se haya creado un riesgo concreto para las personas.',c:'Que dicha tasa sea superior a 0,50 mg/litro en aire espirado.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.379.2 CP: para el delito se requiere que el vehículo sea a motor o ciclomotor (a). No se requiere riesgo concreto (es delito de peligro abstracto) ni la tasa mínima es 0,50 sino 0,60 mg/l.'}},
{n:25, q:'Constituye delito la conducción de un vehículo de motor con una tasa de alcohol en aire espirado que supere los:', o:{a:'0,60 mg/litro.',b:'0,45 mg/litro.',c:'0,25 mg/litro.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.379.2 CP: la tasa que hace constitutiva de delito la conducción es superior a 0,60 mg/litro en aire espirado.'}},
{n:26, q:'Constituye delito la conducción de un vehículo de motor con una tasa de alcohol en sangre que supere los:', o:{a:'0,60 mg/litro.',b:'1,2 gr/litro.',c:'0,25 mg/litro.',d:'0,8 gr/litro.'}, correct:'b', why:{b:'Art.379.2 CP: la tasa en sangre que hace constitutiva de delito es superior a 1,2 g/litro.'}},
{n:27, q:'El art.379.2 del Código Penal castiga con la pena de prisión de 3 a 6 meses o multa de 6 a 12 meses, o con la de trabajos en beneficio de la comunidad de 31 a 90 días, y, en cualquier caso, privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a 1 y hasta 4 años:', o:{a:'Al que condujere un vehículo a motor o ciclomotor bajo la influencia de drogas tóxicas, sustancias psicotrópicas o bebidas alcohólicas.',b:'Al que condujere un vehículo a motor o ciclomotor con una tasa de alcohol en aire espirado superior a 0,60 mg/litro, o con una tasa de alcohol en sangre superior a 1,2 gr/litro.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.379.2 CP: ambas conductas (influencia de drogas/alcohol (a) y tasas objetivas superiores (b)) están sancionadas con las mismas penas.'}},
{n:28, q:'No constituye delito:', o:{a:'Conducir un ciclomotor bajo la influencia de drogas tóxicas.',b:'Conducir un vehículo a motor bajo la influencia de bebidas alcohólicas.',c:'Conducir una bicicleta bajo la influencia de bebidas alcohólicas.',d:'Todas las conductas anteriores son constitutivas de delito.'}, correct:'c', why:{c:'Art.379.2 CP: el delito solo aplica a vehículos a motor y ciclomotores. Conducir una bicicleta bajo la influencia de alcohol no constituye delito (sí puede ser infracción administrativa).'}},
{n:29, q:'El conductor de un vehículo de movilidad personal, implicado en un accidente de circulación, que arroja una tasa de 0,8 mg de alcohol por litro de aire espirado debe ser considerado autor de...', o:{a:'Un delito del artículo 383 del Código Penal.',b:'Una infracción administrativa muy grave a la Ley de Seguridad Vial.',c:'Un delito del artículo 379.2 del Código Penal.',d:'No comete infracción alguna.'}, correct:'b', why:{b:'Los vehículos de movilidad personal no son vehículos a motor ni ciclomotores a efectos penales (art.379 CP), por lo que la conducción con alcohol constituye infracción administrativa, no delito penal.'}},
{n:30, q:'En nuestro Código Penal, el delito de conducción a velocidad excesiva se castiga en el artículo...', o:{a:'379.1',b:'379.2',c:'379.3',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.379.1 CP: el delito de conducción a velocidad excesiva está tipificado en el artículo 379.1 del CP.'}},
{n:31, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un vehículo de movilidad personal a una velocidad superior en 60 Km/hora en vía urbana a la permitida reglamentariamente.',b:'Conducir un ciclomotor a una velocidad superior en 80 Km/hora en vía interurbana a la permitida reglamentariamente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.379.1 CP: el delito de velocidad excesiva en ciclomotor en vía interurbana requiere superar en 80 km/h la velocidad permitida (b). En vehículo de movilidad personal no aplica el art.379 CP.'}},
{n:32, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir cualquier vehículo a una velocidad superior en 60 Km/hora en vía urbana a la permitida reglamentariamente.',b:'Conducir un turismo a una velocidad superior en 80 Km/hora en vía interurbana a la permitida reglamentariamente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.379.1 CP: el delito solo aplica a vehículos a motor y ciclomotores. Conducir un turismo (vehículo a motor) a >80 km/h sobre el límite interurbano es delito (b). "Cualquier vehículo" en vía urbana a >60 km/h es incorrecto (a).'}},
{n:33, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un turismo a una velocidad superior en 80 Km/hora en vía urbana a la permitida reglamentariamente.',b:'Conducir cualquier vehículo de motor a una velocidad superior en 80 Km/hora en vía interurbana a la permitida reglamentariamente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.379.1 CP: superar en 80 km/h la velocidad máxima en vía interurbana (b) y en vía urbana (a) son ambas constitutivas del delito de velocidad excesiva.'}},
{n:34, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un vehículo de motor o un ciclomotor a velocidad superior en sesenta kilómetros por hora en vía urbana o en ochenta kilómetros por hora en vía interurbana a la permitida reglamentariamente.',b:'Conducir a una velocidad anormalmente reducida por autopista o autovía.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.379.1 CP: el delito de velocidad excesiva se comete cuando se supera la velocidad permitida en más de 60 km/h en vía urbana o más de 80 km/h en vía interurbana.'}},
{n:35, q:'El Señor X conduce un turismo a una velocidad de 75 Km/hora por una calle de la ciudad, que tiene limitada la velocidad a 40 km/h. ¿Qué tipo de infracción ha cometido?', o:{a:'Un delito del artículo 379.1 del Código Penal.',b:'Una infracción administrativa grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',c:'Una infracción administrativa muy grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',d:'Un delito del artículo 380 del Código Penal.'}, correct:'c', why:{c:'75 km/h en zona de 40 km/h supone un exceso de 35 km/h. No supera los 60 km/h sobre el límite urbano exigidos para el delito (art.379.1 CP). Constituye infracción administrativa muy grave.'}},
{n:36, q:'En nuestro Código Penal, el delito de conducción a velocidad excesiva se castiga con las penas de...', o:{a:'Prisión de tres a seis meses y con la de multa de seis a dieciocho meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.',b:'Prisión de tres a seis meses o con la de multa de seis a dieciocho meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a dos y hasta cuatro años.',c:'Prisión de tres a seis meses o con la de multa de seis a doce meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cinco años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.379.1 CP: la pena es prisión 3-6 meses O multa 6-18 meses O TBC 31-90 días, y privación del derecho a conducir >1 y hasta 4 años. Ninguna opción lo describe exactamente correcto.'}},
{n:37, q:'En nuestro Código Penal, el delito del artículo 379.1 se castiga con las penas de...', o:{a:'Prisión de tres meses a un año o con la de multa de seis a dieciocho meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.',b:'Prisión de tres a seis meses o con la de multa de seis a doce meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.',c:'Prisión de tres a seis meses y con la de multa de seis a doce meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días, y, en cualquier caso, con la de privación del derecho a conducir vehículos a motor y ciclomotores por tiempo superior a uno y hasta cuatro años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.379.1 CP: la pena es prisión 3-6 meses O multa 6-18 meses O TBC 31-90 días, y privación del derecho a conducir >1 y hasta 4 años. Ninguna opción reproduce exactamente el texto.'}},
{n:38, q:'En nuestro Código Penal, el delito de conducción temeraria se castiga en el artículo...', o:{a:'380.',b:'379.2.',c:'379.1.',d:'382.'}, correct:'a', why:{a:'Art.380 CP: el delito de conducción con temeridad manifiesta poniendo en concreto peligro la vida o integridad de las personas está tipificado en el artículo 380 del CP.'}},
{n:39, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir cualquier vehículo con temeridad manifiesta.',b:'Conducir cualquier vehículo de motor con temeridad manifiesta.',c:'Conducir cualquier vehículo de motor o ciclomotor con temeridad manifiesta',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.380 CP: el delito de conducción temeraria requiere no solo temeridad manifiesta sino también que se ponga en concreto peligro la vida o integridad de las personas. La temeridad sola, sin peligro concreto, no es el tipo del art.380 sino del 381.'}},
{n:40, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un vehículo a motor o ciclomotor con temeridad manifiesta, poniendo en concreto peligro la vida de las personas.',b:'Conducir un vehículo a motor o ciclomotor con temeridad manifiesta, poniendo en concreto peligro los bienes de las personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.380 CP: el delito exige temeridad manifiesta poniendo en concreto peligro la vida o integridad física de las personas (a). No se incluye el peligro para bienes (b).'}},
{n:41, q:'Constituye delito del artículo 380 del Código Penal...', o:{a:'Conducir un vehículo a motor o ciclomotor con manifiesto desprecio por la vida o los bienes de las personas.',b:'Conducir un vehículo a motor o ciclomotor con temeridad manifiesta, poniendo en concreto peligro la integridad de las personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.380.1 CP: el delito consiste en conducir con temeridad manifiesta poniendo en concreto peligro la vida o integridad física de las personas (b). El manifiesto desprecio sin peligro concreto sería el art.381.'}},
{n:42, q:'Para que exista delito de conducción de vehículo a motor con temeridad manifiesta del artículo 380 del Código Penal, se requiere...', o:{a:'Que se haya producido un resultado lesivo para las personas.',b:'Que se ponga en concreto peligro la vida o integridad de las personas.',c:'Que se circule a una velocidad superior en 60 Km/hora a la máxima permitida en vía urbana, o superior en 80 Km/hora a la máxima permitida en vía interurbana.',d:'Que se conduzca con manifiesto desprecio por la vida de los demás.'}, correct:'b', why:{b:'Art.380.1 CP: para el delito de conducción temeraria se requiere poner en concreto peligro la vida o integridad de las personas (b). No se requiere resultado lesivo ni velocidades concretas.'}},
{n:43, q:'La conducción de un vehículo a motor o ciclomotor con temeridad manifiesta poniendo en concreto peligro la vida o la integridad de las personas:', o:{a:'Constituye un delito leve.',b:'Constituye infracción de carácter muy grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',c:'Se castiga con las penas de prisión de 3 a 6 meses y privación del derecho de conducir de 1 a 6 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.380.1 CP: la conducción temeraria con peligro concreto es un delito menos grave (no leve), y la pena es prisión 6 meses-2 años y privación del derecho a conducir 1-6 años. Ninguna opción es exacta.'}},
{n:44, q:'El que condujere un vehículo a motor o un ciclomotor con temeridad manifiesta y pusiera en concreto peligro la vida o la integridad de las personas, será castigado con las penas de:', o:{a:'Prisión de 6 meses a 1 año y privación del derecho a conducir estos vehículos por tiempo superior a 1 y hasta 6 años.',b:'Prisión de 6 meses a 2 años y privación del derecho a conducir estos vehículos por tiempo superior a 1 y hasta 6 años.',c:'Prisión de 6 meses a 1 año y privación del derecho a conducir estos vehículos por tiempo superior a 1 y hasta 4 años.',d:'Prisión de 6 meses a 2 años y privación del derecho a conducir estos vehículos por tiempo superior a 1 y hasta 4 años.'}, correct:'b', why:{b:'Art.380.1 CP: la pena es prisión de 6 meses a 2 años y privación del derecho a conducir de más de 1 año y hasta 6 años.'}},
{n:45, q:'En el artículo 380.2 del Código Penal se reputa conducción manifiestamente temeraria...', o:{a:'Cuando supone un peligro abstracto la vida o la integridad física de las personas.',b:'La conducción en vía urbana a una velocidad superior en 60 Km/hora a la reglamentariamente establecida, llevada a cabo bajo los efectos de drogas tóxicas, estupefacientes o sustancias psicotrópicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.380.2 CP: se reputa conducción manifiestamente temeraria la conducción en vía urbana a >60 km/h sobre el límite bajo los efectos de drogas/alcohol.'}},
{n:46, q:'En el artículo 380.2 del Código Penal se reputa conducción manifiestamente temeraria...', o:{a:'La conducción de vehículo a motor o ciclomotor en vía urbana a una velocidad superior en 60 Km/hora a la reglamentariamente establecida, llevada a cabo bajo la influencia de bebidas alcohólicas.',b:'La conducción de vehículo a motor o ciclomotor en vía interurbana a una velocidad superior en 80 Km/hora a la reglamentariamente establecida, y con una tasa de alcohol en aire espirado de 0,65 mg/l.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.380.2 CP: la concurrencia de exceso de velocidad (>60 km/h en urbana o >80 en interurbana) con influencia de alcohol/drogas se reputa conducción manifiestamente temeraria.'}},
{n:47, q:'Se reputa conducción manifiestamente temeraria, de acuerdo con lo previsto en el artículo 380.2 del Código Penal:', o:{a:'Conducir a una velocidad superior en sesenta km/hora en vía urbana y con una tasa de alcohol en aire espirado superior a 0,60 mg/litro.',b:'Conducir a una velocidad superior en ochenta km/hora en vía interurbana y con una tasa de alcohol en aire espirado superior a 0,40 mg/litro.',c:'Conducir a una velocidad superior en sesenta km/hora en vía urbana y con una tasa de alcohol en sangre superior a 0,60 mg/litro.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.380.2 CP: la conducción manifiestamente temeraria se da cuando se supera en >60 km/h el límite urbano Y hay tasa de alcohol en aire espirado superior a 0,60 mg/l (a).'}},
{n:48, q:'El Sr. X es sorprendido por la Policía Local cuando circulaba a 130 km/hora por una vía urbana que tiene la velocidad limitada a 50 km/h, y con una tasa de alcohol en aire espirado de 0,55 mg/l. De acuerdo con lo anterior, indique cuál de las siguientes actuaciones es correcta:', o:{a:'Instrucción de diligencias penales por un delito de conducción manifiestamente temeraria del artículo 380.2 del Código Penal.',b:'Formulación de dos denuncias por otras tantas infracciones a la Legislación sobre Tráfico, circulación de vehículos a motor o seguridad Vial.',c:'Instrucción de diligencias penales por un delito de velocidad excesiva del artículo 379.1 del Código Penal y formulación de una denuncia administrativa por superar las tasas de alcohol reglamentariamente establecidas.',d:'Instrucción de diligencias penales por un delito de velocidad excesiva del artículo 379.1 del Código Penal y, dependiendo de que se aprecie, o no, influencia del alcohol en la conducción, instrucción de diligencias penales por un delito de conducción bajo la influencia de bebidas alcohólicas, o formulación de una denuncia administrativa por superar las tasas de alcohol reglamentariamente establecidas.'}, correct:'a', why:{a:'130 km/h en zona de 50 km/h = exceso de 80 km/h (supera el umbral de 60 km/h en urbana) + tasa de 0,55 mg/l en aire. La concurrencia de ambas circunstancias se reputa conducción manifiestamente temeraria del art.380.2 CP.'}},
{n:49, q:'En el artículo 380.2 del Código Penal se reputa conducción manifiestamente temeraria...', o:{a:'La conducción en la que concurrieren las circunstancias previstas en el apartado primero y en el inciso primero del apartado segundo del artículo 379 del Código Penal.',b:'La conducción en la que concurrieren las circunstancias en el apartado primero y en el apartado segundo del artículo 379 del Código Penal.',c:'La conducción en la que concurrieren las circunstancias previstas en el apartado segundo y en el inciso primero del apartado primero del artículo 379 del Código Penal.',d:'La conducción en la que concurrieren las circunstancias previstas en el apartado primero y en el inciso segundo del apartado segundo del artículo 379 del Código Penal.'}, correct:'a', why:{a:'Art.380.2 CP: se reputa conducción manifiestamente temeraria la que concurran las circunstancias del art.379.1 (velocidad excesiva) y del inciso primero del art.379.2 (influencia de drogas/alcohol).'}},
{n:50, q:'En nuestro Código Penal, el delito de conducción temeraria con manifiesto desprecio por la vida de los demás, se castiga en el artículo...', o:{a:'382.',b:'381.',c:'379.',d:'380.'}, correct:'b', why:{b:'Art.381 CP: el delito de conducción con manifiesto desprecio por la vida de los demás está tipificado en el artículo 381 del CP.'}},
{n:51, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir una motocicleta con temeridad manifiesta y con manifiesto desprecio por la vida de los demás.',b:'Conducir un vehículo para personas de movilidad reducida con temeridad manifiesta y manifiesto desprecio por la vida de los demás.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.381 CP: el delito se aplica a vehículos a motor y ciclomotores; una motocicleta (a) y un vehículo para personas de movilidad reducida (b) son vehículos a motor.'}},
{n:52, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir una bicicleta con temeridad manifiesta y con manifiesto desprecio por la vida de los demás.',b:'Conducir un vehículo de movilidad personal con temeridad manifiesta y con manifiesto desprecio por la vida de los demás.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.381 CP: el delito solo aplica a vehículos a motor y ciclomotores. Bicicletas y vehículos de movilidad personal no están incluidos.'}},
{n:53, q:'En el artículo 381.1 del Código Penal se castiga...', o:{a:'La conducción manifiestamente temeraria.',b:'La conducción manifiestamente temeraria poniendo en concreto peligro la vida o la integridad física de las personas.',c:'La conducción manifiestamente temeraria, con manifiesto desprecio por la vida de los demás, que suponga concreto peligro para la vida o integridad física de estos.',d:'La conducción manifiestamente temeraria, con manifiesto desprecio por la vida de los demás, sin poner en riesgo la vida o la integridad física de las personas.'}, correct:'c', why:{c:'Art.381.1 CP: se castiga la conducción manifiestamente temeraria, con manifiesto desprecio por la vida de los demás, que suponga concreto peligro para la vida o integridad física.'}},
{n:54, q:'En el artículo 381.2 del Código Penal se castiga...', o:{a:'La conducción manifiestamente temeraria.',b:'La conducción manifiestamente temeraria poniendo en concreto peligro la vida o la integridad física de las personas.',c:'La conducción manifiestamente temeraria, con manifiesto desprecio por la vida de los demás, poniendo en riesgo la vida o la integridad física de las personas.',d:'La conducción manifiestamente temeraria, con manifiesto desprecio por la vida de los demás, sin poner en riesgo la vida o la integridad física de las personas.'}, correct:'d', why:{d:'Art.381.2 CP: se castiga la conducción con manifiesto desprecio por la vida de los demás SIN poner en concreto riesgo la vida o integridad (la puesta en peligro concreto corresponde al art.381.1).'}},
{n:55, q:'El que con manifiesto desprecio por la vida de los demás, condujere un vehículo a motor o ciclomotor con temeridad manifiesta, poniendo en concreto peligro la vida o la integridad de las personas, será castigado con las penas de:', o:{a:'Prisión de 2 a 4 años, multa de 6 a 12 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 6 a 10 años.',b:'Prisión de 2 a 5 años, multa de 12 a 24 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 6 a 10 años.',c:'Prisión de 1 a 4 años, multa de 6 a 12 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 6 a 10 años.',d:'Prisión de 2 a 5 años, multa de 6 a 18 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 6 a 10 años.'}, correct:'b', why:{b:'Art.381.1 CP: la pena es prisión de 2 a 5 años, multa de 12 a 24 meses y privación del derecho a conducir de 6 a 10 años.'}},
{n:56, q:'El que con manifiesto desprecio por la vida de los demás, condujere un vehículo a motor o ciclomotor con temeridad manifiesta, sin poner en concreto peligro la vida o la integridad de las personas, será castigado con las penas de:', o:{a:'Prisión de 1 a 2 años, multa de 6 a 12 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 6 a 10 años.',b:'Prisión de 6 meses a 2 años, multa de 6 a 12 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 6 a 10 años.',c:'Prisión de 1 a 2 años, multa de 6 a 12 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 6 a 10 años.',d:'Prisión de 6 meses, multa de 6 a 18 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 6 a 10 años.'}, correct:'b', why:{b:'Art.381.2 CP: la pena es prisión de 6 meses a 2 años, multa de 6 a 12 meses y privación del derecho a conducir de 6 a 10 años.'}},
{n:57, q:'En nuestro Código Penal, el delito de conducción sin permiso, o conducción ilegal, se castiga en el artículo...', o:{a:'382.',b:'383.',c:'384.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.384 CP: el delito de conducción sin permiso o conducción ilegal está tipificado en el artículo 384 del CP.'}},
{n:58, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un vehículo a motor, tras haber sido privado cautelarmente del permiso o licencia por decisión administrativa.',b:'Conducir un ciclomotor, tras haber sido privado definitivamente del permiso o licencia por decisión judicial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.384 CP: es delito conducir tras haber sido privado definitivamente del permiso por decisión judicial (b). La privación cautelar administrativa (a) no es exactamente el supuesto del art.384.'}},
{n:59, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir una motocicleta tras haber sido privado cautelarmente del permiso o licencia por decisión judicial.',b:'Conducir un vehículo de movilidad personal, tras haber sido privado definitivamente del permiso o licencia por decisión judicial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.384 CP: conducir tras haber sido privado cautelarmente del permiso por decisión judicial (a) es delito. Los vehículos de movilidad personal no están incluidos en el art.384 (b).'}},
{n:60, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir cualquier vehículo sin haber obtenido nunca permiso o licencia de conducción.',b:'Conducir un ciclomotor, en caso de pérdida de vigencia del permiso o licencia de conducción por pérdida total de los puntos legalmente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.384 CP: conducir tras perder el permiso por pérdida total de puntos (b) es delito. Conducir "cualquier vehículo" sin permiso (a) incluye vehículos no motorizados que no están en el art.384.'}},
{n:61, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir un turismo sin haber obtenido nunca permiso o licencia de conducción.',b:'Conducir un cuatriciclo ligero, en caso de pérdida de vigencia del permiso o licencia de conducción por pérdida total de los puntos asignados legalmente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.384 CP: conducir un turismo sin haber obtenido nunca permiso (a) y conducir tras pérdida total de puntos (b) son ambos delitos.'}},
{n:62, q:'De conformidad con la Jurisprudencia del Tribunal Supremo, contenida en la STS 854/2021, constituye delito contra la seguridad vial...', o:{a:'Conducir al amparo de un permiso de conducción de un país extranjero tras la pérdida de vigencia del permiso de conducción expedido en España.',b:'La conducción de vehículos y ciclomotores cuando se tiene suspendido el permiso o licencia por resolución de la autoridad administrativa.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'STS 854/2021: constituye delito del art.384 CP conducir amparado en un permiso extranjero tras haber perdido la vigencia del permiso español, ya que equivale a conducir sin permiso válido en España.'}},
{n:63, q:'Constituye delito contra la seguridad vial...', o:{a:'Conducir con un permiso o licencia que no es válido para el tipo de vehículo que se conduce.',b:'Conducir un vehículo que precisa de permiso de conducción, siendo titular únicamente de una licencia de conducción.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.384 CP: conducir con permiso no válido para ese tipo de vehículo (a) y conducir vehículo que requiere permiso siendo titular solo de licencia (b) son conductas constitutivas de delito.'}},
{n:64, q:'Constituye delito contra la seguridad vial...', o:{a:'La conducción de vehículo a motor o ciclomotor siendo titular de un permiso o licencia de conducción expedido por un país extranjero, que no tiene validez en España.',b:'La conducción con el permiso de conducción caducado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.384 CP: conducir con permiso extranjero sin validez en España (a) es constitutivo de delito. Conducir con permiso caducado (b) es infracción administrativa, no delito.'}},
{n:65, q:'El delito del artículo 384 del Código Penal...', o:{a:'Es un delito de peligro abstracto.',b:'No requiere de la creación de ningún riesgo concreto para la seguridad vial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.384 CP: el delito de conducción sin permiso es un delito de peligro abstracto (a) que no requiere la creación de un riesgo concreto para la seguridad vial (b).'}},
{n:66, q:'En lo que respecta al delito del artículo 384 del Código Penal...', o:{a:'Debe ser considerado cooperador necesario quien cede el vehículo para su conducción a otra persona, a sabiendas de que carece de habilitación administrativa para ello.',b:'Debe ser considerado autor mediato quien se vale de un inimputable para conducir el vehículo de manera ilegal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.384 CP: quien cede el vehículo sabiendo que el conductor carece de permiso es cooperador necesario (a), y quien usa a un inimputable como instrumento es autor mediato (b).'}},
{n:67, q:'Constituye el hecho de conducir un vehículo de motor o ciclomotor...', o:{a:'Tras haber sido privado definitivamente del permiso o licencia de conducción por decisión judicial.',b:'Tras haber sido privado cautelarmente del permiso o licencia de conducción por decisión judicial.',c:'Sin haber obtenido nunca el permiso o licencia de conducción.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.384 CP: todas esas conductas (privación definitiva judicial (a), privación cautelar judicial (b) y nunca haber tenido permiso (c)) son constitutivas del delito de conducción sin permiso.'}},
{n:68, q:'El Sr. X conduce el turismo de su propiedad teniendo el permiso de conducción suspendido por resolución firme de la Jefatura Provincial de Tráfico. En función de lo anterior, indique la respuesta correcta:', o:{a:'El Sr. X es autor de un delito del artículo 383 del Código Penal.',b:'El Sr. X es autor de un delito del artículo 384 del Código Penal.',c:'El Sr. X comete una infracción administrativa de carácter muy grave.',d:'El Sr. X comete una infracción administrativa de carácter grave.'}, correct:'c', why:{c:'La suspensión del permiso por resolución administrativa firme (no judicial) no constituye el delito del art.384 CP, sino una infracción administrativa muy grave a la Ley de Tráfico.'}},
{n:69, q:'El Sr. X conduce un turismo con un permiso de conducción expedido por la República de Senegal, que carece de validez en España por no cumplir los requisitos administrativos exigidos reglamentariamente. En función de lo anterior, indique la respuesta correcta:', o:{a:'El Sr. X es autor de un delito del artículo 383 del Código Penal.',b:'El Sr. X es autor de un delito del artículo 384 del Código Penal.',c:'El Sr. X comete una infracción administrativa de carácter muy grave.',d:'El Sr. X comete una infracción administrativa de carácter grave.'}, correct:'b', why:{b:'Art.384 CP: conducir con un permiso extranjero sin validez en España equivale a conducir sin permiso, constituyendo delito del art.384 CP.'}},
{n:70, q:'El delito del artículo 384 del Código Penal está castigado con las penas de...', o:{a:'Prisión de tres a seis años o con la de multa de doce a veinticuatro meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días.',b:'Prisión de tres a seis meses o con la de multa de dieciocho a veinticuatro meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días.',c:'Prisión de tres a seis meses y multa de doce a veinticuatro meses, o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días.',d:'Prisión de tres a seis meses o con la de multa de doce a veinticuatro meses o con la de trabajos en beneficio de la comunidad de treinta y uno a noventa días.'}, correct:'d', why:{d:'Art.384 CP: el delito de conducción sin permiso se castiga con prisión de 3 a 6 meses O multa de 12 a 24 meses O TBC de 31 a 90 días.'}},
{n:71, q:'En nuestro Código Penal, el delito de negativa al sometimiento de las pruebas legalmente establecidas para la comprobación de las tasas de alcoholemia y presencia de drogas tóxicas en los conductores, se castiga en el artículo...', o:{a:'382.',b:'383.',c:'384.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.383 CP: el delito de negativa a someterse a las pruebas de alcoholemia o drogas está tipificado en el artículo 383 del CP.'}},
{n:72, q:'El conductor de un vehículo a motor que, requerido por un agente de la autoridad, se negare a someterse a las pruebas legalmente establecidas para la comprobación de la presencia de drogas tóxicas, estupefacientes y sustancias psicotrópicas...', o:{a:'Será castigado con prisión de 6 meses a 1 año o privación del derecho a conducir vehículos a motor por tiempo superior a 1 y hasta 4 años.',b:'Será castigado con prisión de 6 meses a 1 año o privación del derecho a conducir vehículos a motor por tiempo superior a 1 y hasta 4 años.',c:'Será castigado con prisión de 3 meses a 1 año o privación del derecho a conducir vehículos a motor por tiempo superior a 1 y hasta 4 años.',d:'Será castigado con prisión de 3 meses a 1 año o privación del derecho a conducir vehículos a motor por tiempo superior a 1 y hasta 4 años.'}, correct:'a', why:{a:'Art.383 CP: la negativa a las pruebas de drogas se castiga con prisión de 6 meses a 1 año o privación del derecho a conducir de más de 1 y hasta 4 años.'}},
{n:73, q:'La negativa del conductor de un ciclomotor a someterse a las pruebas legalmente establecidas para la comprobación de las tasas de alcoholemia...', o:{a:'Se castiga como delito en el artículo 383 del Código Penal.',b:'Es un delito leve.',c:'Se castiga con las penas de multa de 3 a 12 meses y privación del derecho a conducir vehículos a motor por tiempo superior a 1 y hasta 4 años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.383 CP: la negativa del conductor de un ciclomotor a las pruebas de alcoholemia es delito tipificado en el art.383 CP (no delito leve).'}},
{n:74, q:'La negativa del conductor de un vehículo de tracción animal a someterse a las pruebas legalmente establecidas para la comprobación de la presencia de drogas tóxicas, estupefacientes y sustancias psicotrópicas...', o:{a:'Se castiga como delito en el artículo 383 del Código Penal.',b:'Constituye infracción administrativa a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',c:'Es atípica penal y administrativamente.',d:'No tiene prevista sanción alguna.'}, correct:'b', why:{b:'Art.383 CP: el delito solo aplica a conductores de vehículos a motor o ciclomotores. El conductor de vehículo de tracción animal que se niega puede incurrir en infracción administrativa, no penal.'}},
{n:75, q:'El conductor que requerido por un agente de la autoridad legalmente establecidas para la comprobación de las tasas de alcoholemia será castigado con las penas de:', o:{a:'Prisión de 1 a 2 años, multa de 6 a 12 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 3 a 6 años.',b:'Prisión de 6 meses a 1 año, multa de 6 a 12 meses y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo de 1 a 4 años.',c:'Prisión de 1 a 2 años y privación del derecho a conducir vehículos a motor y ciclomotores por un periodo superior a 1 y hasta 4 años.',d:'Prisión de 6 meses a 1 año o privación del derecho a conducir vehículos a motor y ciclomotores por un periodo superior a 1 y hasta 4 años.'}, correct:'d', why:{d:'Art.383 CP: la negativa a las pruebas de alcoholemia se castiga con prisión de 6 meses a 1 año O privación del derecho a conducir de más de 1 y hasta 4 años.'}},
{n:76, q:'La negativa del conductor de un ciclo de motor a someterse a las pruebas legalmente establecidas para la comprobación de la presencia de drogas tóxicas, estupefacientes y sustancias psicotrópicas...', o:{a:'Se castiga como delito en el artículo 383 del Código Penal.',b:'Constituye infracción administrativa a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',c:'Es atípica penal y administrativamente.',d:'No tiene prevista sanción alguna.'}, correct:'b', why:{b:'Un ciclo de motor (ciclomotor de pedales) puede no quedar incluido en el ámbito del art.383 CP. La negativa a la prueba constituiría infracción administrativa.'}},
{n:77, q:'Constituye delito contra la seguridad vial...', o:{a:'La negativa a realizar la segunda de las pruebas de determinación del grado de impregnación alcohólica mediante aire espirado, tras haber llevado a cabo la primera de las pruebas, por parte del conductor de un vehículo de movilidad personal.',b:'La negativa a realizar la segunda de las pruebas de determinación del grado de impregnación alcohólica mediante aire espirado por parte del conductor de un ciclomotor, aunque solicite un análisis de sangre a efectos de contraste.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.383 CP: la negativa a la segunda prueba de alcoholemia por parte del conductor de un ciclomotor es delito (b), aunque solicite contraste. La negativa por conductor de vehículo de movilidad personal no está en el art.383 (a).'}},
{n:78, q:'El Tribunal Supremo (STS 210/2017) considera que constituye delito contra la seguridad vial...', o:{a:'La negativa de cualquier conductor de vehículo a motor a realizar las pruebas de determinación del grado de impregnación alcohólica, aunque se halle en óptimas condiciones para conducir y no haya ingerido ni una sola gota de alcohol.',b:'La negativa de un peatón, implicado en un accidente de circulación, a someterse a las pruebas legalmente establecidas para la determinación de su grado de impregnación alcohólica.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'STS 210/2017: constituye delito la negativa a la prueba alcoholométrica de cualquier conductor de vehículo a motor, aunque no haya bebido ni esté en malas condiciones. El peatón no está incluido en el art.383.'}},
{n:79, q:'En lo que respecta al delito del artículo 383 del Código Penal, el Tribunal Supremo ha sentenciado...', o:{a:'Que no se vulnera el principio de proporcionalidad, ni el "non bis in idem", cuando se produce la condena simultánea por los delitos de conducción influenciada y negativa a someterse a las pruebas legalmente establecidas.',b:'Que nada impide que pueda aplicarse la eximente incompleta o atenuante de embriaguez a este delito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'TS: no hay vulneración del principio non bis in idem por condena simultánea de ambos delitos (a), y puede aplicarse la eximente incompleta de embriaguez al art.383 (b).'}},
{n:80, q:'En nuestro Código Penal, los delitos de creación de grave riesgo a la circulación, se castigan en el artículo...', o:{a:'381.',b:'383.',c:'384.',d:'385.'}, correct:'d', why:{d:'Art.385 CP: los delitos de creación de grave riesgo para la circulación (colocación de obstáculos, derramamiento de sustancias deslizantes, etc.) están tipificados en el artículo 385 del CP.'}},
{n:81, q:'El que origine un grave riesgo para la circulación, mediante la mutación de la señalización...', o:{a:'Será considerado autor de un delito del artículo 385 del Código Penal.',b:'Será considerado autor de un delito leve del artículo 385 bis del Código Penal.',c:'Será castigado con las penas de prisión de 6 meses a 2 años y multa de 12 a 24 meses, o con la de trabajos en beneficio de la comunidad de 1 a 40 días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.385.2ª CP: mutar la señalización es una de las conductas que origina grave riesgo para la circulación, constituyendo delito del art.385 CP.'}},
{n:82, q:'El que origine un grave riesgo para la circulación, por no restablecer la seguridad de la vía, cuando tenga la obligación de hacerlo...', o:{a:'Incurrirá en una infracción de carácter muy grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',b:'Será considerado autor de un delito del art. 385 del Código Penal.',c:'Incurrirá en una infracción de carácter grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.385.3ª CP: no restablecer la seguridad de la vía cuando se tiene obligación de hacerlo es otra modalidad del delito de creación de grave riesgo para la circulación del art.385.'}},
{n:83, q:'Retirar, ocultar, alterar o deteriorar la señalización permanente u ocasional de la vía...', o:{a:'Constituye infracción de carácter muy grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',b:'Constituye delito del art. 385 del Código Penal.',c:'Constituye infracción de carácter grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.385.2ª CP: retirar, ocultar, alterar o deteriorar la señalización constituye delito de creación de grave riesgo para la circulación.'}},
{n:84, q:'Arrojar a la vía o en sus inmediaciones objetos que obstaculicen la libre circulación constituye:', o:{a:'Un delito del art. 385 del Código Penal.',b:'Un delito del artículo 380 del Código Penal.',c:'Una infracción de carácter grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.385.1ª CP: arrojar objetos que obstaculicen la libre circulación es una conducta que puede originar grave riesgo y constituir delito del art.385 CP.'}},
{n:85, q:'Originar un grave riesgo para la circulación, mediante la colocación en la vía de obstáculos imprevisibles constituye...', o:{a:'Un delito del art. 385 del Código Penal.',b:'Un delito del artículo 380 del Código Penal.',c:'Un delito del artículo 386 del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.385.1ª CP: colocar obstáculos imprevisibles en la vía es una de las conductas del delito de creación de grave riesgo del art.385 CP.'}},
{n:86, q:'Originar un grave riesgo para la circulación, mediante el derramamiento en la vía de sustancias deslizantes o inflamables constituye...', o:{a:'Un delito del art. 385 del Código Penal.',b:'Un delito del artículo 380 del Código Penal.',c:'Una infracción de carácter muy grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.',d:'Una infracción de carácter grave a la Ley sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.'}, correct:'a', why:{a:'Art.385.1ª CP: el derramamiento de sustancias deslizantes o inflamables en la vía que origine grave riesgo constituye delito del art.385 CP.'}},
{n:87, q:'No restablecer la seguridad de una vía, cuando exista obligación de hacerlo:', o:{a:'Es delito en todo caso.',b:'Es delito si con ello se origina un grave riesgo a la circulación.',c:'Es delito solo si se hace con manifiesto desprecio por la vida o la integridad física de los demás.',d:'Únicamente constituye infracción administrativa a la Legislación sobre Tráfico, Circulación de Vehículos a Motor y Seguridad Vial.'}, correct:'b', why:{b:'Art.385.3ª CP: no restablecer la seguridad de la vía es delito cuando se origina un grave riesgo a la circulación (b). No es delito en todo caso.'}},
{n:88, q:'El art.385 del Código Penal castiga al que origine un grave riesgo para la circulación...', o:{a:'Colocando en la vía obstáculos imprevisibles, derramando en la misma sustancias deslizantes o inflamables o mutando, sustrayendo o anulando la señalización.',b:'Derramando en la vía sustancias deslizantes o inflamables.',c:'Mutando, sustrayendo o anulando la señalización.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.385 CP: todas las conductas son modalidades del delito: obstáculos imprevisibles, sustancias deslizantes/inflamables y mutación de señalización (d).'}},
{n:89, q:'El delito del artículo 385 del Código Penal se castiga con las penas de...', o:{a:'Prisión de 6 a 18 meses o con las de multa de 12 a 24 meses y trabajos en beneficio de la comunidad de 10 a 40 días.',b:'Prisión de 6 meses a 2 años o con las de multa de 6 a 18 meses, o trabajos en beneficio de la comunidad de 10 a 40 días.',c:'Prisión de 6 meses a 2 años o con las de multa de 12 a 24 meses y trabajos en beneficio de la comunidad de 10 a 40 días.',d:'Prisión de 6 a 18 meses, multa de 12 a 24 meses, y trabajos en beneficio de la comunidad de 10 a 40 días.'}, correct:'c', why:{c:'Art.385 CP: la pena es prisión de 6 meses a 2 años O multa de 12 a 24 meses Y TBC de 10 a 40 días.'}},
{n:90, q:'En nuestro Código Penal, los delitos de omisión del deber de socorro están regulados en su...', o:{a:'Título XVII.',b:'Título XIV.',c:'Título X.',d:'Título IX.'}, correct:'a', why:{a:'Los delitos de omisión del deber de socorro están en el Título XVII del Libro II del CP (arts.195 y 196).'}},
{n:91, q:'En nuestro Código Penal, el delito de abandono del lugar del accidente está regulado en...', o:{a:'El capítulo IV del Título IX.',b:'El capítulo II del Título XVII.',c:'El capítulo IV del Título XVII.',d:'El capítulo IV del Título XVIII.'}, correct:'c', why:{c:'El delito de abandono del lugar del accidente (art.382 bis CP) está regulado en el Capítulo IV del Título XVII del Libro II del CP.'}},
{n:92, q:'En nuestro Código Penal, el delito de abandono del lugar del accidente está regulado en...', o:{a:'El artículo 382.',b:'El artículo 382 bis.',c:'El artículo 382 ter.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'El delito de abandono del lugar del accidente está regulado en el artículo 382 bis del CP.'}},
{n:93, q:'Constituye delito contra la seguridad vial...', o:{a:'El delito de omisión del deber de socorro.',b:'El delito de abandono del lugar del accidente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Son delitos contra la seguridad vial tanto la omisión del deber de socorro (art.195 CP relacionado con el tráfico) (a) como el abandono del lugar del accidente (art.382 bis CP) (b).'}},
{n:94, q:'Constituye delito contra la seguridad vial...', o:{a:'No socorrer a una persona que se halle desamparada y en peligro manifiesto y grave cuando pudiere hacerlo sin riesgo propio ni de terceros.',b:'No demandar con urgencia auxilio ajeno, cuando no se pudiese socorrer a una persona desamparada y en peligro manifiesto y grave.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.195.1 y 195.2 CP: la omisión del deber de socorro incluye no socorrer directamente (a) y no pedir auxilio urgente cuando no se puede hacerlo directamente (b).'}},
{n:95, q:'De conformidad con lo dispuesto en el artículo 195 del Código Penal, constituye delito de omisión del deber de socorro...', o:{a:'No socorrer a una persona que se halle desamparada y en peligro manifiesto y grave cuando pudiere hacerlo sin riesgo propio ni de terceros.',b:'No demandar con urgencia auxilio ajeno, cuando no se pudiese socorrer a una persona desamparada y en peligro manifiesto y grave.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.195.1 y 195.2 CP: ambas conductas son delito de omisión del deber de socorro.'}},
{n:96, q:'Los delitos de omisión del deber de socorro contenidos en los apartados 1 y 2 del artículo 195 del Código Penal, se castigan con la pena de...', o:{a:'Prisión de 6 a 18 meses.',b:'Multa de 12 a 24 meses.',c:'Trabajos en beneficio de la comunidad de 31 a 90 días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.195.1 y 195.2 CP: los delitos de omisión del deber de socorro se castigan con multa de 3 a 12 meses (no con las penas indicadas).'}},
{n:97, q:'En los delitos de omisión del deber de socorro, si la víctima lo fuere por accidente ocasionado fortuitamente por el que omitió el auxilio, se impondrá la pena de...', o:{a:'Prisión de 6 a 18 meses.',b:'Multa de 12 a 24 meses.',c:'Trabajos en beneficio de la comunidad de 31 a 90 días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.195.3 CP: si la víctima lo es por accidente fortuito causado por quien omite el auxilio, se impone prisión de 6 meses a 1 año y multa de 6 a 12 meses (ninguna opción coincide).'}},
{n:98, q:'En los delitos de omisión del deber de socorro se impondrá la pena de prisión de 6 meses a cuatro años, cuando...', o:{a:'La víctima lo fuere por conducta dolosa del que omitió el auxilio.',b:'La víctima lo fuere por accidente ocasionado fortuitamente por el que omitió el auxilio.',c:'La víctima lo fuere por accidente debido a la imprudencia del que omitió el auxilio.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'Art.195.3 CP: la pena de prisión de 6 meses a 4 años (y multa) se aplica cuando la víctima lo es por accidente ocurrido por imprudencia del que omite el auxilio. Pero la opción d dice "ninguna es correcta", que es incorrecta. La correcta sería c. Se mantiene d como pendiente de solucionario.'}},
{n:99, q:'Los delitos de omisión del deber de socorro...', o:{a:'Requieren de una o más personas fallecidas, o con lesiones de las previstas en los artículos 147.1, 149 o 150 del Código Penal.',b:'Requieren que la persona que omite el auxilio haya participado en el accidente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.195 CP: los delitos de omisión del deber de socorro no requieren fallecidos ni lesiones graves (a), ni que el omitente haya participado en el accidente (b). Basta con no socorrer a quien está en peligro manifiesto y grave.'}},
{n:100, q:'El delito de abandono del lugar del accidente del artículo 382 bis del Código Penal requiere que...', o:{a:'La víctima lo fuere por accidente ocasionado fortuitamente por el que omitió el auxilio.',b:'La conducta punible no se halle contemplada en el artículo 195 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.382 bis CP: el delito de abandono del lugar del accidente requiere que sea accidente fortuito causado por el conductor que abandona (a) y que la conducta no esté contemplada en el art.195 (b, es decir, que no haya obligación directa de socorro).'}},
{n:101, q:'El delito de abandono del lugar del accidente del artículo 382 bis del Código Penal requiere que...', o:{a:'El abandono se produzca voluntariamente y sin que concurra riesgo propio o de terceros.',b:'El accidente se haya producido de manera fortuita.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.382 bis CP: requiere abandono voluntario sin riesgo propio o para terceros (a) y que el accidente sea fortuito (b).'}},
{n:102, q:'El delito de abandono del lugar del accidente del artículo 382 bis del Código Penal requiere que...', o:{a:'En el accidente hubieren fallecido una o varias personas.',b:'En el accidente se causare alguna de las lesiones a que se refieren los artículos 147.1, 147.2, 149 y 150 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.382 bis CP: el delito requiere que en el accidente haya fallecidos (a) o lesiones de los arts.147.1, 147.2, 149 o 150 CP (b).'}},
{n:103, q:'El delito de abandono del lugar del accidente del artículo 382 bis del Código Penal se castiga con prisión de 1 a 4 años, y privación del derecho a conducir vehículos a motor y ciclomotores de uno a cuatro años, cuando...', o:{a:'Los hechos tuvieran su origen en una acción imprudente del conductor.',b:'El origen de los hechos que da lugar al abandono fuere fortuito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.382 bis.1 CP: la pena de prisión de 1 a 4 años y privación del derecho de 1 a 4 años se aplica cuando el origen del abandono es fortuito (b).'}},
{n:104, q:'El delito de abandono del lugar del accidente del artículo 382 bis del Código Penal se castiga con prisión de 6 meses a 4 años, y privación del derecho a conducir vehículos a motor y ciclomotores de uno a cuatro años, cuando...', o:{a:'Los hechos tuvieran su origen en una acción imprudente del conductor.',b:'El origen de los hechos que da lugar al abandono fuere fortuito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.382 bis.2 CP: la pena de prisión de 6 meses a 4 años (y privación de 1 a 4 años) se aplica cuando el abandono tiene su origen en una acción imprudente del conductor (a).'}},
{n:105, q:'El delito de abandono del lugar del accidente del artículo 382 bis del Código Penal se castiga con prisión de 3 a 6 meses, y privación del derecho a conducir vehículos a motor y ciclomotores de 6 meses a dos años, cuando...', o:{a:'Los hechos tuvieran su origen en una acción imprudente del conductor.',b:'El origen de los hechos que da lugar al abandono fuere fortuito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.382 bis CP no prevé la pena de prisión de 3-6 meses y privación 6m-2 años para ninguno de los supuestos de abandono del lugar del accidente.'}},
{n:106, q:'Indique la respuesta correcta...', o:{a:'El delito de abandono del lugar del accidente solo puede cometerlo una persona implicada en el mismo.',b:'El delito de omisión del deber de socorro puede cometerlo cualquier persona, aunque no haya tenido ninguna implicación en los hechos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.382 bis CP: el abandono del lugar del accidente solo lo puede cometer quien participó en el accidente (a); el deber de socorro del art.195 CP alcanza a cualquier persona que encuentre a alguien en peligro (b).'}},
{n:107, q:'Según el artículo 382 del Código Penal, cuando además del riesgo prevenido, se produjese un resultado lesivo constitutivo de delito, cualquiera que sea su gravedad, los jueces o tribunales apreciarán tan solo la infracción más gravemente penada, aplicando la pena en su mitad superior y condenando, en todo caso, al resarcimiento de la responsabilidad civil que se hubiera originado. Esta previsión es aplicable:', o:{a:'A todos los delitos contra la seguridad vial.',b:'Al delito consistente en originar grave riesgo para la circulación del artículo 385 del Código Penal.',c:'Al delito de conducción de vehículo a motor o ciclomotor bajo la influencia de bebidas alcohólicas del artículo 379.2 del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.382 CP: la regla concursal (infracción más grave en mitad superior + responsabilidad civil) se aplica al delito de grave riesgo para la circulación del art.385 CP cuando produce un resultado lesivo.'}},
{n:108, q:'Según el art.382 del C.P. cuando, además del riesgo prevenido, se produjese un resultado lesivo constitutivo de delito, cualquiera que sea su gravedad, los jueces o tribunales apreciarán tan solo la infracción más gravemente penada, aplicando la pena en su mitad superior y condenando, en todo caso, al resarcimiento de la responsabilidad civil que se hubiera originado. Esta previsión es aplicable:', o:{a:'Al delito de omisión del deber de socorro del artículo 195 del Código Penal.',b:'Al delito de conducción temeraria del artículo 380 del Código Penal.',c:'Al delito de negativa a realizar las pruebas legalmente establecidas para la comprobación de las tasas de alcoholemia del artículo 383 CP.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.382 CP: la regla concursal también aplica al delito de conducción temeraria del art.380 CP cuando produce un resultado lesivo.'}},
{n:109, q:'Según el artículo 382 del Código Penal cuando además del riesgo prevenido, se produjese un resultado lesivo constitutivo de delito, cualquiera que sea su gravedad, los jueces o tribunales apreciarán tan solo la infracción más gravemente penada, aplicando la pena en su mitad superior y condenando, en todo caso, al resarcimiento de la responsabilidad civil que se hubiera originado. Esta previsión es aplicable:', o:{a:'Al delito de abandono del lugar del accidente del artículo 382 bis del Código Penal',b:'Al delito de conducción a velocidad excesiva del artículo 379.1 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.382 CP: la regla concursal se aplica también al abandono del lugar del accidente (art.382 bis) (a) y a la conducción a velocidad excesiva (art.379.1) (b) cuando producen resultado lesivo.'}},
{n:110, q:'El vehículo a motor o ciclomotor utilizado se considerará instrumento de delito a los efectos de los artículos 127 y 128 del Código Penal:', o:{a:'En el delito de conducción de vehículo a motor bajo la influencia de bebidas alcohólicas.',b:'En el delito de conducción con temeridad manifiesta, poniendo en concreto peligro la vida o la integridad de las personas.',c:'En el delito de conducción temeraria con manifiesto desprecio del art.381.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.385 bis CP: el vehículo se considerará instrumento del delito en todos los delitos de los arts.379, 380, 381 y 382 bis, entre otros.'}},
{n:111, q:'El vehículo a motor o ciclomotor utilizado se considerará instrumento del delito:', o:{a:'En el delito de omisión del deber de socorro.',b:'En el delito de abandono del lugar del accidente.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.385 bis CP: el vehículo se considera instrumento del delito también en la omisión del deber de socorro (a) y en el abandono del lugar del accidente (b).'}},
{n:112, q:'Según el artículo 385 ter del Código Penal, el Juez o Tribunal, razonándolo en la sentencia, podrá rebajar en un grado la pena de prisión en atención a la menor entidad del riesgo causado y a las demás circunstancias del hecho. Esta previsión es aplicable...', o:{a:'A los delitos de conducción del artículo 385 del código penal.',b:'A los delitos de conducción bajo la influencia de bebidas alcohólicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.385 ter CP: la posibilidad de rebajar la pena en un grado por menor entidad del riesgo se aplica a los delitos del art.385 (creación de grave riesgo para la circulación).'}},
{n:113, q:'Según el artículo 385 ter del Código Penal, el Juez o Tribunal, razonándolo en la sentencia, podrá rebajar en un grado la pena de prisión en atención a la menor entidad del riesgo causado y a las demás circunstancias del hecho. Esta previsión es aplicable...', o:{a:'A los delitos de conducción a velocidad excesiva.',b:'A los delitos de omisión del deber de socorro.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.385 ter CP: la rebaja en un grado por menor entidad del riesgo se aplica específicamente a los delitos de los arts.379, 380, 381 y 382 bis. El art.385 ter no menciona expresamente los delitos de omisión del deber de socorro.'}},
{n:114, q:'Según el artículo 385 ter del Código Penal, el Juez o Tribunal, razonándolo en la sentencia, podrá rebajar en un grado la pena de prisión en atención a la menor entidad del riesgo causado y a las demás circunstancias del hecho. Esta previsión es aplicable...', o:{a:'A los delitos de conducción temeraria del artículo 380 del código penal.',b:'A los delitos de conducción temeraria con manifestó desprecio del artículo 381 del código penal.',c:'Al delito de conducción sin permiso del artículo 384 del código penal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.385 ter CP: la rebaja por menor entidad del riesgo es aplicable a los delitos de los arts.379, 380, 381, 382 bis y 384, entre otros.'}},
];
